  'cert.uploadErr.fileTooLarge': { en: 'That file is too large — the maximum is 3 MB.', ko: '파일이 너무 큽니다 — 최대 3MB입니다.', ar: 'هذا الملف كبير جدًّا — الحدّ الأقصى 3 ميغابايت.', es: 'El archivo es demasiado grande: el máximo es 3 MB.', fr: 'Ce fichier est trop volumineux — la taille maximale est de 3 Mo.', zh: '该文件过大 — 上限为 3 MB。', ru: 'Файл слишком большой — максимум 3 МБ.' },
  'cert.uploadErr.mimeMismatch': { en: 'That file does not appear to be a valid image or PDF.', ko: '해당 파일이 올바른 이미지 또는 PDF가 아닌 것 같습니다.', ar: 'لا يبدو أن هذا الملف صورة أو PDF صالح.', es: 'Ese archivo no parece ser una imagen o un PDF válido.', fr: 'Ce fichier ne semble pas être une image ou un PDF valide.', zh: '该文件似乎不是有效的图片或 PDF。', ru: 'Похоже, этот файл не является допустимым изображением или PDF.' },
  'cert.uploadErr.tooMany': { en: 'Upload limit reached — please contact support to update your ID.', ko: '업로드 한도에 도달했습니다 — 신분증을 변경하려면 지원팀에 문의해 주세요.', ar: 'بلغت الحدّ الأقصى للرفع — يُرجى التواصل مع الدعم لتحديث هويتك.', es: 'Ha alcanzado el límite de subidas; contacte con soporte para actualizar su documento de identidad.', fr: 'Limite de téléversements atteinte — veuillez contacter l’assistance pour mettre à jour votre pièce d’identité.', zh: '已达到上传次数上限 — 请联系支持团队以更新您的身份证件。', ru: 'Достигнут лимит загрузок — обратитесь в поддержку, чтобы обновить удостоверение личности.' },
