  'sup.yourTickets': { en: 'Your tickets ({count})', ko: '내 지원 티켓 ({count})', ar: 'تذاكر الدعم الخاصة بك ({count})', es: 'Tus tickets de soporte ({count})', fr: 'Vos tickets d\'assistance ({count})', zh: '您的支持工单 ({count})', ru: 'Ваши обращения в поддержку ({count})' },
  'sup.noTickets': { en: 'No tickets yet — anything you raise appears here with its full history.', ko: '아직 티켓이 없습니다. 문의를 등록하면 전체 기록과 함께 여기에 표시됩니다.', ar: 'لا توجد تذاكر بعد — أي طلب تقدّمه سيظهر هنا مع سجله الكامل.', es: 'Aún no hay tickets: cualquier consulta que abras aparecerá aquí con su historial completo.', fr: 'Aucun ticket pour le moment — toute demande que vous soumettez apparaîtra ici avec son historique complet.', zh: '暂无工单——您提交的任何请求都会连同完整记录显示在此处。', ru: 'Обращений пока нет — любое созданное вами обращение появится здесь вместе с полной историей.' },
