  'sup.ticketCreated': { en: 'Ticket {ref} created — we\'ll reply here and by email.', ko: '티켓 {ref}이(가) 생성되었습니다 — 여기와 이메일로 답변드리겠습니다.', ar: 'تم إنشاء التذكرة {ref} — سنرد عليك هنا وعبر البريد الإلكتروني.', es: 'Ticket {ref} creado: te responderemos aquí y por correo electrónico.', fr: 'Ticket {ref} créé — nous vous répondrons ici et par e-mail.', zh: '工单 {ref} 已创建——我们将在此处及通过电子邮件回复您。', ru: 'Обращение {ref} создано — мы ответим здесь и по электронной почте.' },
  'sup.createError': { en: 'Could not create the ticket. Please try again.', ko: '티켓을 생성할 수 없습니다. 다시 시도해 주세요.', ar: 'تعذّر إنشاء التذكرة. يُرجى المحاولة مرة أخرى.', es: 'No se pudo crear el ticket. Inténtalo de nuevo.', fr: 'Impossible de créer le ticket. Veuillez réessayer.', zh: '无法创建工单，请重试。', ru: 'Не удалось создать обращение. Пожалуйста, попробуйте ещё раз.' },
  'sup.replyError': { en: 'Could not send your reply. Please try again.', ko: '답장을 보낼 수 없습니다. 다시 시도해 주세요.', ar: 'تعذّر إرسال ردك. يُرجى المحاولة مرة أخرى.', es: 'No se pudo enviar tu respuesta. Inténtalo de nuevo.', fr: 'Impossible d\'envoyer votre réponse. Veuillez réessayer.', zh: '无法发送您的回复，请重试。', ru: 'Не удалось отправить ответ. Пожалуйста, попробуйте ещё раз.' },
  'sup.ratePrompt': { en: 'How did we do? Rate this conversation:', ko: '어땠나요? 이 대화를 평가해 주세요:', ar: 'كيف كان أداؤنا؟ قيِّم هذه المحادثة:', es: '¿Qué tal lo hicimos? Valora esta conversación:', fr: 'Comment avons-nous fait ? Évaluez cette conversation :', zh: '我们的服务如何？请为本次对话评分：', ru: 'Как мы справились? Оцените этот диалог:' },
  'sup.rateStar': { en: 'Rate {n} out of 5', ko: '5점 만점에 {n}점 주기', ar: 'قيّم {n} من 5', es: 'Valorar con {n} de 5', fr: 'Noter {n} sur 5', zh: '评 {n} 分（满分 5 分）', ru: 'Оценить на {n} из 5' },
  'sup.rateThanks': { en: 'Thank you — your rating has been recorded.', ko: '감사합니다 — 평가가 기록되었습니다.', ar: 'شكرًا لك — تم تسجيل تقييمك.', es: 'Gracias: tu valoración se ha registrado.', fr: 'Merci — votre évaluation a été enregistrée.', zh: '谢谢——您的评分已记录。', ru: 'Спасибо — ваша оценка сохранена.' },
  'sup.rateError': { en: 'Could not record your rating. Please try again.', ko: '평가를 기록할 수 없습니다. 다시 시도해 주세요.', ar: 'تعذّر تسجيل تقييمك. يُرجى المحاولة مرة أخرى.', es: 'No se pudo registrar tu valoración. Inténtalo de nuevo.', fr: 'Impossible d\'enregistrer votre évaluation. Veuillez réessayer.', zh: '无法记录您的评分，请重试。', ru: 'Не удалось сохранить оценку. Пожалуйста, попробуйте ещё раз.' },

