  'xd.opensInfo': { en: 'Launch activates {n} minutes before your slot and stays open for a 30-minute grace period.', ko: '시험 시작은 예약 시간 {n}분 전에 활성화되며, 30분의 유예 시간 동안 열려 있습니다.', ar: 'يُفعَّل البدء قبل موعدك بـ {n} دقيقة ويبقى مفتوحًا لفترة سماح مدتها 30 دقيقة.', es: 'El inicio se activa {n} minutos antes de su cita y permanece abierto durante un período de gracia de 30 minutos.', fr: 'Le lancement s’active {n} minutes avant votre créneau et reste ouvert pendant un délai de grâce de 30 minutes.', zh: '开考通道在预约时间前 {n} 分钟开放，并保留 30 分钟宽限期。', ru: 'Запуск активируется за {n} минут до вашего слота и остаётся открытым в течение 30-минутного льготного периода.' },
  'xd.windowOpen': { en: 'Launch window open — closes {time}', ko: '시험 시작 가능 — {time}에 마감', ar: 'نافذة البدء مفتوحة — تُغلق {time}', es: 'Ventana de inicio abierta; cierra {time}', fr: 'Fenêtre de lancement ouverte — ferme {time}', zh: '开考通道已开放 — {time} 关闭', ru: 'Окно запуска открыто — закрывается {time}' },
