  'xd.starting': { en: 'Starting…', ko: '시작 중…', ar: 'جارٍ البدء…', es: 'Iniciando…', fr: 'Démarrage…', zh: '正在开始…', ru: 'Запуск…' },
  'xd.openDesktop': { en: 'Open in the PCI Secure Exam app instead', ko: '대신 PCI Secure Exam 앱에서 열기', ar: 'الفتح في تطبيق PCI Secure Exam بدلًا من ذلك', es: 'Abrir en la aplicación PCI Secure Exam', fr: 'Ouvrir plutôt dans l’application PCI Secure Exam', zh: '改用 PCI Secure Exam 应用打开', ru: 'Открыть в приложении PCI Secure Exam' },
  'xd.needReadiness': { en: 'Run and pass the system readiness check', ko: '시스템 준비 상태 점검을 실행하고 통과하세요', ar: 'شغّل فحص جاهزية النظام واجتَزْه', es: 'Ejecute y apruebe la comprobación de preparación del sistema', fr: 'Exécutez et réussissez la vérification de préparation du système', zh: '请运行并通过系统就绪检查', ru: 'Выполните и пройдите проверку готовности системы' },
