  'xr.holdTitle': { en: 'Result on hold — under review', ko: '결과 보류 — 검토 중', ar: 'النتيجة معلّقة — قيد المراجعة', es: 'Resultado en espera; en revisión', fr: 'Résultat en attente — en cours d’examen', zh: '成绩暂缓——审核中', ru: 'Результат на удержании — идёт проверка' },
  'xr.holdDefault': { en: 'Your submission is being verified. PCI will notify you once the review is complete.', ko: '제출물을 확인하는 중입니다. 검토가 끝나면 PCI가 알려 드립니다.', ar: 'يجري التحقق من تقديمك. ستُخطرك PCI فور اكتمال المراجعة.', es: 'Su envío se está verificando. PCI le avisará cuando la revisión termine.', fr: 'Votre soumission est en cours de vérification. PCI vous informera dès la fin de l’examen.', zh: '正在核验您的提交。审核完成后 PCI 会通知您。', ru: 'Ваша работа проверяется. PCI уведомит вас по завершении проверки.' },
  'xr.holdNote': { en: 'No pass/fail outcome is shown until the review is resolved. You do not need to do anything.', ko: '검토가 끝날 때까지 합격/불합격 결과가 표시되지 않습니다. 별도 조치는 필요 없습니다.', ar: 'لا تُعرض نتيجة نجاح/رسوب حتى تُحسم المراجعة. لا يلزمك فعل شيء.', es: 'No se muestra aprobado/suspenso hasta resolver la revisión. No necesita hacer nada.', fr: 'Aucun résultat réussite/échec n’est affiché avant la fin de l’examen. Vous n’avez rien à faire.', zh: '审核完成前不会显示通过/未通过。您无需任何操作。', ru: 'До завершения проверки итог «сдал/не сдал» не отображается. Ничего делать не нужно.' },
  'xr.backDash': { en: 'Back to my dashboard', ko: '대시보드로 돌아가기', ar: 'العودة إلى لوحتي', es: 'Volver a mi panel', fr: 'Retour à mon tableau de bord', zh: '返回我的主页', ru: 'Вернуться на панель' },
