  'rr.bandAt': { en: 'At target', ko: '목표 도달', ar: 'عند الهدف', es: 'En el objetivo', fr: 'Au niveau de la cible', zh: '达到目标', ru: 'На уровне цели' },
  'rr.bandBelow': { en: 'Below target', ko: '목표 미달', ar: 'أدنى من الهدف', es: 'Inferior al objetivo', fr: 'En dessous de la cible', zh: '低于目标', ru: 'Ниже цели' },
